package thaumcraft.test;
import java.util.*;
import com.mojang.authlib.GameProfile;
import net.minecraft.core.*;
import net.minecraft.core.component.DataComponents;
import net.minecraft.network.chat.Component;
import net.minecraft.server.level.*;
import net.minecraft.world.*;
import net.minecraft.world.item.*;
import net.minecraft.world.level.block.Blocks;
import net.minecraftforge.event.TickEvent;
import net.minecraftforge.event.server.ServerStartedEvent;
import net.minecraftforge.eventbus.api.listener.SubscribeEvent;
import net.minecraftforge.fml.common.Mod;
import thaumcraft.*;
import thaumcraft.thaumaturgy.*;
import thaumcraft.aura.*;
import thaumcraft.crystals.*;
import thaumcraft.research.*;
import static thaumcraft.test.ThaumaturgyProbe.*;
@Mod.EventBusSubscriber(modid=Thaumcraft.MODID)
public final class DeepDevicesProbe {
    public static final BlockPos Q=new BlockPos(128,205,8);public static final UUID OWNER=UUID.fromString("c73342f2-eb20-484c-bb34-1289f7d46001");static ServerPlayer p;static FocalEntity table;static int ticks;static boolean prepared,done;
    public static FocusProgram node(String medium,String effect){return new FocusProgram(medium,List.of(new FocusProgram.Effect(effect,1,1)));}
    public static FocusProgram graph(){return node("projectile","break").withChild(0,node("bolt","break").withChild(0,node("touch","air")));}
    public static ItemStack focus(){var item=item("focus_3");item.set(ThaumaturgyContent.PROGRAM.get(),graph());item.set(DataComponents.CUSTOM_NAME,Component.literal("Nested focus"));return item;}
    public static void pouch(ServerPlayer p){var bag=item("focus_pouch");var all=new ArrayList<ItemStack>();for(int i=0;i<18;i++)all.add(ItemStack.EMPTY);all.set(0,focus());all.set(17,item("focus_1"));FocusPouch.save(bag,all);var caster=item("caster_basic");p.setItemInHand(InteractionHand.MAIN_HAND,caster);check(FocusPouch.cycle(p,caster,bag)&&ItemStack.matches(caster.get(ThaumaturgyContent.FOCUS.get()),focus()),"Bag focus lost graph/name");check(FocusPouch.cycle(p,caster,bag)&&FocusPouch.contents(bag).get(17).get(ThaumaturgyContent.PROGRAM.get()).equals(graph()),"Bag swap duplicated/lost installed focus");check(FocusPouch.cycle(p,caster,bag)&&caster.get(ThaumaturgyContent.FOCUS.get()).get(ThaumaturgyContent.PROGRAM.get()).equals(graph()),"Bag cycle did not recover named nested focus");p.setItemInHand(InteractionHand.MAIN_HAND,bag);int locked=p.getInventory().getSelectedSlot();var menu=new PouchMenu(90,p.getInventory(),bag,locked);int slot=menu.findSlot(p.getInventory(),locked).orElseThrow();menu.clicked(slot,0,net.minecraft.world.inventory.ContainerInput.THROW,p);check(p.getMainHandItem()==bag&&menu.quickMoveStack(p,slot).isEmpty(),"Open bag could be dropped/shift moved");menu.clicked(0,locked,net.minecraft.world.inventory.ContainerInput.SWAP,p);check(p.getMainHandItem()==bag,"Hotbar swap removed open pouch");check(!menu.getSlot(0).mayPlace(item("focus_pouch"))&&menu.getSlot(0).mayPlace(focus()),"Bag accepts nested containers");Thaumcraft.LOGGER.info("DEEP_POUCH_OK: 18 slots, exact named graph, physical cycles and menu locks");}
    public static void costs(ServerPlayer p,FocalEntity f){knowledge(p);f.draft=graph();f.inventory.setItem(0,focus());var m=new FocalMenu(91,p.getInventory(),f);check(m.clickMenuButton(p,22)&&m.value(25)==1&&m.value(3)==1,"Cannot enter continuation");check(m.clickMenuButton(p,22)&&m.value(25)==2&&m.value(3)==0,"Cannot enter grandchild");check(m.clickMenuButton(p,3)&&f.draft.at(List.of(0,0)).effects().getFirst().power()==2,"Deep power edit failed");check(m.clickMenuButton(p,23)&&m.value(25)==1&&m.clickMenuButton(p,23)&&m.value(25)==0,"Parent navigation failed");f.draft=graph();int i=1;for(var c:graph().crystals().entrySet())f.inventory.setItem(i++,CrystalContent.essence(c.getKey(),c.getValue()));p.experienceLevel=40;var full=ResearchService.state(p);KnowledgeStore.write(p,full.stage("FOCUSELEMENTAL",0));check(!f.start(p)&&p.experienceLevel==40,"Missing deep research paid costs");KnowledgeStore.write(p,full);AuraManager.addVis(p.level(),Q,1000);check(f.start(p)&&p.experienceLevel==40-graph().levels(),"Deep graph payment failed");check(!m.clickMenuButton(p,22),"Pending graph can be changed");}
    public static void rareEarth(ServerPlayer p){var l=p.level();var tool=new ItemStack(Items.NETHERITE_PICKAXE);int gems=0,rare=0;for(int i=0;i<512;i++)for(var stack:net.minecraft.world.level.block.Block.getDrops(Blocks.DIAMOND_ORE.defaultBlockState(),l,Q,null,p,tool)){if(stack.is(Items.DIAMOND))gems+=stack.getCount();if(stack.is(thaumcraft.content.SimpleContent.ITEMS.get("nugget_rareearth").get()))rare+=stack.getCount();}check(gems==512&&rare>0,"Rare earth modifier did not preserve native loot or add bonus: "+rare);tool.enchant(l.registryAccess().lookupOrThrow(net.minecraft.core.registries.Registries.ENCHANTMENT).getOrThrow(net.minecraft.world.item.enchantment.Enchantments.SILK_TOUCH),1);for(int i=0;i<32;i++){var drops=net.minecraft.world.level.block.Block.getDrops(Blocks.DIAMOND_ORE.defaultBlockState(),l,Q,null,p,tool);check(drops.size()==1&&drops.getFirst().is(Items.DIAMOND_ORE),"Rare earth ignored Silk Touch");}check(ResearchCatalog.BY_KEY.get("GRAPPLEGUN").stages().getFirst().items().getFirst().matches(item("nugget_rareearth")),"Grapple research rare earth remains unavailable");Thaumcraft.LOGGER.info("DEEP_RARE_EARTH_OK: original additional drops {}, 512 native diamonds, Silk Touch and reachable grapple requirement",rare);}
    @SubscribeEvent public static void start(ServerStartedEvent e){var mode=System.getProperty("thaumcraft.thaumaturgyProbe","");if(!mode.equals("deep-write")&&!mode.equals("deep-read")&&!mode.equals("deep-rules"))return;var l=e.getServer().overworld();l.setChunkForced(8,0,true);p=new ServerPlayer(e.getServer(),l,new GameProfile(OWNER,"DeepProbe"),ClientInformation.createDefault()){@Override public void sendSystemMessage(Component c,boolean overlay){}@Override public void sendOverlayMessage(Component c){}@Override protected ItemCooldowns createItemCooldowns(){return new ItemCooldowns();}};p.setPos(128.5,206,8.5);if(mode.equals("deep-write")){l.setBlockAndUpdate(Q,Blocks.AIR.defaultBlockState());l.setBlockAndUpdate(Q,ThaumaturgyContent.TABLE.get().defaultBlockState());}table=(FocalEntity)l.getBlockEntity(Q);check(table!=null,"Missing deep table");}
    @SubscribeEvent public static void tick(TickEvent.ServerTickEvent.Post e){var mode=System.getProperty("thaumcraft.thaumaturgyProbe","");if(done||(!mode.equals("deep-write")&&!mode.equals("deep-read")&&!mode.equals("deep-rules"))||++ticks<40)return;var l=e.server().overworld();if(mode.equals("deep-rules")){rareEarth(p);done=true;e.server().halt(false);return;}if(mode.equals("deep-read")){if(ticks==40){rareEarth(p);check(table.working()&&table.draft.equals(graph())&&table.remaining()<table.total(),"Paid deep graph was not resumed");var bag=table.inventory.getItem(9);check(FocusPouch.contents(bag).stream().filter(s->s.getItem() instanceof FocusItem).count()==1,"Pouch inventory not saved");check(table.inventory.getItem(8).get(ThaumaturgyContent.FOCUS.get()).get(ThaumaturgyContent.PROGRAM.get()).equals(graph()),"Caster deep graph not saved");var t=(TurretEntity)l.getBlockEntity(Q.east(4));check(t!=null&&t.ammo()==12&&t.mode()==1&&OWNER.equals(t.owner()),"Turret ammo/mode/owner not restored");}if(table.working())return;check(table.inventory.getItem(0).get(ThaumaturgyContent.PROGRAM.get()).equals(graph()),"Deep job output changed");done=true;Thaumcraft.LOGGER.info("DEEP_RESTART_OK: exact paid graph, pouch, caster and turret owner/ammo/mode restored");e.server().halt(false);return;}
        if(!prepared){pouch(p);var bag=p.getMainHandItem().copy();var caster=item("caster_basic");caster.set(ThaumaturgyContent.FOCUS.get(),focus());costs(p,table);table.inventory.setItem(9,bag);table.inventory.setItem(8,caster);l.setBlockAndUpdate(Q.east(4),ThaumaturgyContent.TURRET_ADVANCED.get().defaultBlockState());var t=(TurretEntity)l.getBlockEntity(Q.east(4));t.claim(p);t.interact(p,new ItemStack(Items.ARROW,12));t.interact(p,new ItemStack(Items.STICK));prepared=true;return;}if(table.remaining()==table.total())return;done=true;Thaumcraft.LOGGER.info("DEEP_WRITE_OK: saved paid nested graph, physical pouch and advanced turret");e.server().halt(false);
    }
}
